import type { PrCheck, PrThread, PrView } from '../types'

const NL = '\n'
const PR_URL = /https:\/\/github\.com\/([\w.-]+\/[\w.-]+)\/pull\/(\d+)/g

/** "owner/repo#123" for each GitHub PR link in the text, in order, without repeats. */
export function prRefs(text: string): string[] {
  return [...new Set([...text.matchAll(PR_URL)].map(m => `${m[1]}#${m[2]}`))]
}

/** "owner/repo#123" as its parts. */
export function parseRef(ref: string): { repo: string; owner: string; name: string; number: string } {
  const [repo = '', number = ''] = ref.split('#')
  const [owner = '', name = ''] = repo.split('/')

  return { repo, owner, name, number }
}

/** The fields `gh pr view --json` returns that the tab uses. */
export const VIEW_FIELDS = 'number,title,url,isDraft,state,baseRefName,mergeable,reviewDecision,statusCheckRollup'

/**
 * Unresolved review threads: the first comment, which states the finding, and
 * who wrote the last one, which says whose turn it is.
 */
export const THREADS_QUERY = `query($owner: String!, $repo: String!, $number: Int!) {
  viewer { login }
  repository(owner: $owner, name: $repo) {
    pullRequest(number: $number) {
      reviewThreads(first: 100) {
        nodes {
          id isResolved isOutdated path line originalLine
          comments(first: 1) { totalCount nodes { author { login } body url } }
          last: comments(last: 1) { nodes { author { login } body url } }
        }
      }
    }
  }
}`

type RollupEntry = {
  __typename?: string
  name?: string
  context?: string
  status?: string
  conclusion?: string
  state?: string
  detailsUrl?: string
  targetUrl?: string
}

/** gh's check rollup as pass, fail, pending or skip; a check run and a commit status spell it differently. */
function bucket(e: RollupEntry): PrCheck['bucket'] {
  const result = (e.conclusion || e.state || '').toUpperCase()
  if (e.status && e.status.toUpperCase() !== 'COMPLETED') return 'pending'
  if (['SUCCESS', 'NEUTRAL'].includes(result)) return 'pass'
  if (['SKIPPED', 'STALE'].includes(result)) return 'skip'
  if (['PENDING', 'EXPECTED', 'QUEUED', 'IN_PROGRESS', ''].includes(result)) return 'pending'

  return 'fail'
}

/** Reads `gh pr view --json VIEW_FIELDS` output; null when it is not that. */
export function readView(ref: string, json: string): Omit<PrView, 'threads' | 'fetchedAt' | 'error'> | null {
  try {
    const v = JSON.parse(json) as Record<string, unknown>
    if (typeof v.number !== 'number') return null
    const rollup = Array.isArray(v.statusCheckRollup) ? (v.statusCheckRollup as RollupEntry[]) : []

    return {
      ref,
      number: v.number,
      title: String(v.title ?? ''),
      url: String(v.url),
      isDraft: v.isDraft === true,
      state: String(v.state ?? 'OPEN'),
      base: String(v.baseRefName ?? ''),
      mergeable: String(v.mergeable ?? 'UNKNOWN'),
      reviewDecision: String(v.reviewDecision ?? ''),
      checks: rollup.map(e => ({
        name: e.name ?? e.context ?? 'check',
        bucket: bucket(e),
        url: e.detailsUrl ?? e.targetUrl ?? null,
      })),
    }
  } catch {
    return null
  }
}

type ThreadNode = {
  id: string
  isResolved: boolean
  isOutdated: boolean
  path: string
  line: number | null
  originalLine: number | null
  comments: { totalCount: number; nodes: { author: { login: string } | null; body: string; url: string }[] }
  last: { nodes: { author: { login: string } | null; body: string; url: string }[] }
}

type ThreadsAnswer = {
  data?: { viewer?: { login: string }; repository?: { pullRequest?: { reviewThreads?: { nodes?: ThreadNode[] } } } }
}

/** Reads the THREADS_QUERY answer: open threads only, oldest first. */
export function readThreads(json: string): PrThread[] {
  try {
    const data = (JSON.parse(json) as ThreadsAnswer).data
    const viewer = data?.viewer?.login

    return (data?.repository?.pullRequest?.reviewThreads?.nodes ?? [])
      .filter(t => !t.isResolved)
      .map(t => {
        const first = t.comments.nodes[0]
        const last = t.comments.totalCount > 1 ? t.last.nodes[0] : undefined
        const reply = last ? { author: last.author?.login ?? 'ghost', body: last.body.trim(), url: last.url } : null

        return {
          id: t.id,
          author: first?.author?.login ?? 'ghost',
          reply,
          isWaiting: (reply?.author ?? first?.author?.login) !== viewer,
          isOutdated: t.isOutdated,
          path: t.path,
          line: t.line ?? t.originalLine,
          body: (first?.body ?? '').trim(),
          replies: Math.max(0, t.comments.totalCount - 1),
          url: first?.url ?? '',
        }
      })
  } catch {
    return []
  }
}

/** Open threads whose last comment someone else wrote: the ones waiting on the person. */
export function waitingThreads(pr: PrView): PrThread[] {
  return pr.threads.filter(t => t.isWaiting)
}

export function checkCounts(pr: PrView): Record<PrCheck['bucket'], number> {
  const counts = { pass: 0, fail: 0, pending: 0, skip: 0 }
  for (const c of pr.checks) counts[c.bucket] += 1

  return counts
}

/** "1 thread waiting on you", "3 threads waiting on you". */
function threadsWaiting(count: number): string {
  return `${count} ${count === 1 ? 'thread' : 'threads'} waiting on you`
}

/** Where a PR stands. A draft is open and not ready, whatever else blocks it. */
export type PrStatus = 'ready' | 'blocked' | 'draft' | 'merged' | 'closed'

/** What stands between the PR and merging, or that it is ready. */
export function readiness(pr: PrView): { status: PrStatus; text: string } {
  if (pr.state === 'MERGED') return { status: 'merged', text: 'Merged' }
  if (pr.state !== 'OPEN') return { status: 'closed', text: 'Closed' }
  const { fail: failing, pending } = checkCounts(pr)
  const open = waitingThreads(pr).length
  const blockers = [
    pr.isDraft ? 'draft' : null,
    pr.mergeable === 'CONFLICTING' ? `conflicts with ${pr.base}` : null,
    failing > 0 ? `${failing} failing ${failing === 1 ? 'check' : 'checks'}` : null,
    pr.reviewDecision === 'CHANGES_REQUESTED' ? 'changes requested' : null,
    open > 0 ? threadsWaiting(open) : null,
    pr.reviewDecision === 'REVIEW_REQUIRED' ? 'needs approval' : null,
    pending > 0 ? `${pending} ${pending === 1 ? 'check' : 'checks'} running` : null,
  ].filter((b): b is string => b !== null)

  return blockers.length === 0
    ? {
        status: 'ready',
        text: `Ready to merge${pr.reviewDecision === 'APPROVED' ? ': approved' : ''}, checks pass, no threads waiting on you`,
      }
    : { status: pr.isDraft ? 'draft' : 'blocked', text: `Blocked: ${blockers.join(', ')}` }
}

/** The band's one-line PR alert: the first open PR that needs the person, or null. */
export function prAttention(views: PrView[]): string | null {
  for (const pr of views) {
    if (pr.state !== 'OPEN') continue
    const open = waitingThreads(pr).length
    if (checkCounts(pr).fail > 0) return `PR #${pr.number} CI failing`
    if (pr.reviewDecision === 'CHANGES_REQUESTED') return `PR #${pr.number} changes requested`
    if (open > 0) return `PR #${pr.number} ${threadsWaiting(open)}`
  }

  return null
}

/**
 * The HTML tags review bots write in comments, such as `<sub>` and `<details>`.
 * Lowercase only, so a type parameter such as `Props<P>` stays.
 */
const HTML_TAG =
  /<\/?(?:a|b|br|code|details|div|em|h[1-6]|hr|i|img|kbd|li|ol|p|pre|span|strong|sub|summary|sup|table|tbody|td|th|thead|tr|ul)\b[^>]*>/g

/**
 * A review comment's Markdown without the HTML that review bots add, and with
 * each image as its alt text, so a bot's `![P1 Badge](…)` reads "P1".
 */
export function readableComment(body: string): string {
  return body
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(HTML_TAG, '')
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, (_, alt: string) => alt.replace(/\s*badge$/i, ''))
    .trim()
}

/** A review comment as one line of plain text, for a row that shows only its start. */
export function commentLine(body: string): string {
  return readableComment(body)
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/^\s*(?:#{1,6}|>)\s*/gm, '')
    .replace(/\*\*|__|`/g, '')
    .replace(/\s+/g, ' ')
}

/** Where a thread sits in the diff: "path:line", or the path alone. */
export function threadWhere(t: PrThread, path = t.path): string {
  return `${path}${t.line ? `:${t.line}` : ''}`
}

export function failingChecks(pr: PrView): PrCheck[] {
  return pr.checks.filter(c => c.bucket === 'fail')
}

function threadText(t: PrThread): string {
  const where = threadWhere(t)

  const opening = [`${where}, from @${t.author}${t.isOutdated ? ' (on an outdated diff)' : ''}:`, t.body, t.url]
  const reply = t.reply ? ['', `Latest reply, from @${t.reply.author}:`, t.reply.body, t.reply.url] : []

  return [...opening, ...reply].join(NL)
}

/** The message each PR button sends to Claude. */
export const prompts = {
  fix: (pr: PrView, check: PrCheck) =>
    [
      `The CI check "${check.name}" is failing on PR #${pr.number} (${pr.url}).`,
      'Find out why from its logs, fix it, and verify the fix. If the fix needs a change to CI configuration, ask me before making it.',
      ...(check.url ? [`Check details: ${check.url}`] : []),
    ].join(NL),
  address: (pr: PrView, threads: PrThread[]) =>
    [
      threads.length === 1
        ? `Address this review comment on PR #${pr.number} (${pr.url}). Fix it in code and verify.`
        : `Address these ${threads.length} review comments on PR #${pr.number} (${pr.url}). Fix each in code and verify.`,
      "Don't reply on GitHub or resolve the threads; tell me what you changed for each.",
      ...threads.map(t => NL + threadText(t)),
    ].join(NL),
  draft: (pr: PrView, t: PrThread) =>
    [
      `Draft a reply to this review comment on PR #${pr.number} (${pr.url}) for me to review. Don't post it.`,
      '',
      threadText(t),
    ].join(NL),
  discuss: (pr: PrView, t: PrThread) =>
    [
      `Let's talk through this review comment on PR #${pr.number} (${pr.url}) before changing anything.`,
      '',
      threadText(t),
    ].join(NL),
}

files..claude-plugin/plugin.json:
{
  "name": "inbox",
  "description": "Collects what is waiting on you in a session: questions, Claude's notes and PR reviews",
  "types": "./types/index.d.ts"
}

files.types/index.d.ts:
/** Where the session stands, as the ledger model last summarized it. */
export type Card = {
  goal: string
  done: string[]
  now: string
  running: string[]
  updatedAt: number
}

/** Something the agent put to the person that is still unanswered. */
export type Item = {
  id: string
  kind: 'question' | 'task'
  /** The agent's own number or id for it ("1", "D3"), so "1. yes" maps back. */
  label: string | null
  ask: string
  options: string[]
  /** The option the agent recommended, exactly as `options` has it. */
  rec: string | null
  /** Steps the agent's reply spelled out, one press each. */
  helps: Help[]
  /** The person-prompt count when the agent asked it. */
  turn: number
  /** When the agent asked it; null for an item saved before the mod kept the time. */
  at: number | null
}

/**
 * A one-press step toward finishing an item. The mod never runs a command:
 * `run` asks Claude to run it, under the usual permission checks, and
 * `terminal` copies one that only the person can run.
 */
export type Help =
  | { kind: 'open'; path: string }
  | { kind: 'copy'; text: string; name: string | null }
  | { kind: 'run'; command: string; name: string | null }
  | { kind: 'terminal'; command: string; name: string | null }
  | { kind: 'link'; url: string; name: string | null }

/** An item that closed, and how. */
export type Closed = {
  id: string
  kind: Item['kind']
  ask: string
  /** The reply's own number for it, when it had one. */
  label?: string
  /** What the pane shows for how it closed, such as the person's answer. */
  outcome: string
  /**
   * How it closed: the person answered it, marked a task done or ran its
   * command, or dismissed it; it expired unanswered; Claude closed it with a
   * reason; or the per-reply update closed it, with an outcome the model wrote.
   */
  how: 'answered' | 'done' | 'dismissed' | 'expired' | 'claude' | 'update'
  at: number
}

/** An item that just closed, and where its row stood among the open items of its kind. */
export type Settled = Closed & { index: number }

/** Something Claude noticed outside the current task and recorded for the person. */
export type Finding = {
  id: string
  kind: 'issue' | 'opportunity'
  title: string
  detail: string
  /** The file it is about, as Claude gave it. */
  path: string | null
  at: number
}

export type PrCheck = { name: string; bucket: 'pass' | 'fail' | 'pending' | 'skip'; url: string | null }

/** An unresolved review thread, told by its first comment. */
export type PrThread = {
  id: string
  author: string
  /** The thread's latest comment, when anyone answered the first. */
  reply: { author: string; body: string; url: string } | null
  /** Someone other than the viewer wrote its last comment, so it waits on them. */
  isWaiting: boolean
  isOutdated: boolean
  path: string
  line: number | null
  body: string
  replies: number
  url: string
}

/** A PR as gh last reported it. */
export type PrView = {
  /** "owner/repo#123" */
  ref: string
  number: number
  title: string
  url: string
  isDraft: boolean
  state: string
  base: string
  mergeable: string
  reviewDecision: string
  checks: PrCheck[]
  threads: PrThread[]
  fetchedAt: number
  /** Why the last fetch failed; the rest is from the fetch before. */
  error: string | null
}

export type Ledger = {
  card: Card | null
  items: Item[]
  closed: Closed[]
  findings: Finding[]
  /** PRs this session created or linked, as "owner/repo#123". */
  prs: string[]
  nextId: number
  /** How many prompts the person has sent this session. */
  turn: number
  /** The turn whose reply added the newest items; 0 when none. */
  batchTurn: number
}

/** Why the session halted outside the conversation, from the error Claude Code classified it with. */
export type Stop = {
  kind: 'sign-in' | 'billing' | 'usage-limit' | 'api-error'
  /** Claude Code's word for the error, such as `authentication_failed`. */
  detail: string
  /** When a usage limit resets, as Claude Code said it: "7:33pm". */
  resets: string | null
  at: number
}

/** A permission prompt or question dialog in the session that waits on the person. */
export type Dialog = {
  kind: 'permission' | 'question'
  text: string
  /** The tool call it is for, so it closes when that call ends. */
  key: string
}

/** `all`: a script that runs the project's checks together, such as `check.sh`. */
export type CheckKind = 'tests' | 'types' | 'lint' | 'build' | 'validate' | 'all'

/**
 * The part of a check's suite one run covered. Both lists empty means the
 * whole suite.
 */
export type Target = {
  /** Files and folders the run named, absolute. */
  paths: string[]
  /** Test-name filters and any argument the inbox could not read, such as `-t=parses dates`. */
  filters: string[]
}

/** The latest result of one check command Claude ran, such as `npm test`, in one folder, for one target. */
export type Check = {
  name: string
  kind: CheckKind
  /** The part of the suite the run covered; empty for the whole suite. */
  target: Target
  /** The folder it ran in, absolute; null for the session's own folder. */
  folder: string | null
  result: 'pass' | 'fail' | 'unknown'
  /** The output's summary line, such as "24 pass, 1 fail". */
  summary: string
  ranAt: number
  /** The top folder of the git repo it ran in, whose edits make it stale; null outside git. */
  repo: string | null
  /**
   * Files it reads changed after it ran: any file for a lint, a validation or
   * a check script, and a file other than Markdown for the rest.
   */
  isStale: boolean
  /** The piece of Claude's command that ran it, as written, such as `npm test > t.log`. */
  command: string
  /** Up to three output lines that name what failed, when the command ran no other check. */
  failures: string[]
  /** A turn of Claude's ended with it failing, so the Needs you tab lists it. */
  isLeftFailing: boolean
  /** The person dismissed its row in the Needs you tab. */
  isDismissed: boolean
  /** The Stop hook already sent Claude back over this result, so it does not again. */
  isSentBack: boolean
  /** When the person pressed Fix on its row, so it no longer waits on them; null before. The next run replaces the result. */
  fixSentAt: number | null
}

/**
 * The working tree's content, read without writing to the repo: HEAD, and the
 * blob id of each path that differs from it ('' for a deleted path).
 */
export type Snapshot = { head: string | null; dirty: Record<string, string> }

/** The checks Claude ran. */
export type Checks = {
  results: Check[]
  /** The session's repos: the one it started in, and each repo where Claude edited a file. Only their results count. */
  repos: string[]
}

export type Presence = {
  lastActiveAt: number
  isAway: boolean
  isUpdating: boolean
  /**
   * `behind` and `failed`: the ledger may have missed a turn, so the next
   * update re-reads the whole conversation. Only `failed` shows in the pane.
   */
  ledgerState: 'current' | 'behind' | 'failed'
  /**
   * The turns started in this process, and how many of them reached the
   * ledger. A load that finds more started than applied catches up.
   */
  turnsStarted: number
  turnsApplied: number
  /** The minute of the last clock tick, so the "last active" text redraws. */
  minute: number
}

/** The most recent other session in this project, offered on a fresh start. */
export type Previous = {
  savedAt: number
  ledger: Ledger
  isBroughtIn: boolean
}

export type Tab = 'needsYou' | 'findings' | 'prs'

/** A tab's selected row: its id, and its position for when that row goes away. */
export type Cursor = { id: string | null; index: number }

/** The PR tab's data: each PR's latest view, the current branch's PR, and whether a fetch runs. */
export type PrViews = { views: Record<string, PrView>; branchRef: string | null; isFetching: boolean }

/** A failing PR check the person pressed Fix on: when, and the check's URL then. A rerun has a new URL, so the mark lapses. */
export type PrFixSent = { at: number; url: string | null }

declare module 'claude-code' {
  interface PluginState {
    inbox: {
      /** The Claude Code theme in use, such as `dark` or `light-ansi`; '' until read. */
      theme: string
      ledger: Ledger
      presence: Presence
      previous: Previous | null
      tab: Tab
      prViews: PrViews
      /** The PR checks the person pressed Fix on, by their row's id. */
      prFixesSent: Record<string, PrFixSent>
      selection: Record<Tab, Cursor>
      stop: Stop | null
      dialogs: Dialog[]
      checks: Checks
      /** Each checked repo's working tree as last read, by its top folder, kept apart from `checks` because no drawing reads it. */
      snapshots: Record<string, Snapshot>
      /** The row whose free-text field is open, if any. */
      typing: string | null
      /** Items that just closed, shown in place with their outcome for a few seconds. */
      settled: Settled[]
      /** The Needs you groups whose closed items show. Each starts folded. */
      unfolded: Item['kind'][]
      /** The pane's list of the keys no row shows is unfolded. */
      isKeyListShown: boolean
      /** A failing check's row shows its output and command under the summary. */
      isCheckDetailShown: boolean
      /** The band and pane show sample entries instead of the session's own, for `/inbox demo`. */
      isDemo: boolean
    }
  }
}
